def findAnagrams(s, p):
    if len(s) < len(p):
        return []
    need = [0] * 26
    win = [0] * 26
    for c in p:
        need[ord(c) - 97] += 1
    m = len(p)
    res = []
    for i, c in enumerate(s):
        win[ord(c) - 97] += 1
        if i >= m:
            win[ord(s[i - m]) - 97] -= 1
        if i >= m - 1 and win == need:
            res.append(i - m + 1)
    return res

