class Solution {
public:
    vector<int> findAnagrams(string s, string p) {
        if (s.size() < p.size()) return {};
        vector<int> need(26, 0), win(26, 0);
        for (char c : p) need[c - 'a']++;
        int m = (int)p.size();
        vector<int> res;
        for (int i = 0; i < (int)s.size(); i++) {
            win[s[i] - 'a']++;
            if (i >= m) win[s[i - m] - 'a']--;
            if (i >= m - 1 && win == need) res.push_back(i - m + 1);
        }
        return res;
    }
};

